mapper.select:
SELECT t.id, t.name, t.source, t.assignee_id, assignee.name AS assignee_name, t.customer_id, customer.name AS customer_name, t.description, t.deadline, t.status, t.report_content, t.ai_reply, t.started_at, t.completed_at, t.report_submitted_at, t.create_time, t.update_time, t.create_user, t.update_user FROM crm_task t LEFT JOIN sys_user assignee ON assignee.id = t.assignee_id LEFT JOIN customer ON customer.id = t.customer_id AND customer.organization_id = t.organization_id WHERE t.organization_id = #{organizationId}
AND t.assignee_id = #{userId}
AND t.assignee_id IS NULL
AND t.assignee_id = #{request.assigneeId}
AND ( t.name LIKE CONCAT('%', #{request.keyword}, '%') OR assignee.name LIKE CONCAT('%', #{request.keyword}, '%') OR customer.name LIKE CONCAT('%', #{request.keyword}, '%') )
AND t.status != 'COMPLETED' AND t.deadline < #{now}
AND t.status = 'COMPLETED'
AND t.status = 'PENDING' AND t.deadline >= #{now}
AND t.status = 'IN_PROGRESS' AND t.deadline >= #{now}
ORDER BY CASE WHEN t.assignee_id IS NULL THEN 0 ELSE 1 END, CASE WHEN t.status != 'COMPLETED' AND t.deadline < #{now} THEN 0 WHEN t.status = 'PENDING' THEN 1 WHEN t.status = 'IN_PROGRESS' THEN 2 ELSE 3 END, t.deadline ASC, t.create_time DESC

SELECT COUNT(*)
FROM customer
WHERE organization_id = #{organizationId}
  AND id = #{customerId}

SELECT COUNT(*)
FROM crm_task
WHERE organization_id = #{organizationId}
  AND business_key = #{businessKey}

SELECT id, name FROM customer WHERE organization_id = #{organizationId}
AND name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY update_time DESC LIMIT 100
